async function request<T>(path:string, token:string, init:RequestInit = {}):Promise<T>{
 const headers = new Headers(init.headers);
 if(token) headers.set("Authorization", "Bearer "+token);
 if(init.body && !(init.body instanceof FormData)) headers.set("Content-Type","application/json");
 const response = await fetch(API+path,{...init,headers});
 if(!response.ok){let message = "Request failed ("+response.status+")";try{const body=await response.json();message=body.detail||message;}catch{}throw new Error(message);}
 if(response.status===204) return undefined as T;
 return response.json() as Promise<T>;
}
const dateText=(value?:string|null)=>value?new Date(value).toLocaleDateString(undefined,{day:"2-digit",month:"short",year:"numeric"}):"—";
function stageDonutGradient(counts:{stage:string;count:number}[]){const palette=["#2563eb","#7c3aed","#0ea5a4","#16a765","#f59e0b","#ec4899","#64748b"];const total=counts.reduce((sum,item)=>sum+item.count,0);if(!total)return "#e8edf5";let cursor=0;const stops=counts.map((item,index)=>{const start=cursor;cursor+=item.count/total*100;return `${palette[index%palette.length]} ${start}% ${cursor}%`;});return `conic-gradient(${stops.join(",")})`;}

function formatComplianceFinding(detail:string){
 const match=detail.match(/^Recorded validity metadata:\s*status=([^;]+);\s*expiry=([^;]+);\s*renewal due=([^.;]+)\.\s*(.*)$/i);
 if(!match)return detail;
 const [,status,expiry,renewal,tail]=match;
 const readableDate=(raw:string)=>{const parsed=new Date(raw.trim().replace(" ","T"));return Number.isNaN(parsed.getTime())?raw.trim():parsed.toLocaleDateString(undefined,{day:"2-digit",month:"short",year:"numeric"});};
 return `Recorded status: ${status.trim()}. Expiry date: ${readableDate(expiry)}. Renewal due: ${readableDate(renewal)}. ${tail.trim()}`.trim();
}
const dateInput=(days:number)=>{const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10);};
