 async function patchItem(path:string,body:unknown,message:string){try{await request(path,token,{method:"PATCH",body:JSON.stringify(body)});notify(message);await loadAll();}catch(e){notify(e instanceof Error?e.message:"Update failed");}}
 async function applyChecklist(){
  if(!docAppId){notify("Choose an application first.");return;}
  setChecklistBusy(true);
  try{await request("/api/v1/applications/"+docAppId+"/document-checklist/apply",token,{method:"POST",body:"{}"});const v=await request<{items:DocumentCheck[];summary:NonNullable<typeof checklistSummary>}>("/api/v1/applications/"+docAppId+"/document-checklist",token);setDocumentChecks(v.items);setChecklistSummary(v.summary);notify("Document checklist applied.");}
  catch(e){notify(e instanceof Error?e.message:"Could not apply checklist");}
  finally{setChecklistBusy(false);}
 }
 async function updateDocumentCheck(check:DocumentCheck,status:string,documentId:number|null=check.document_id){
  try{await request("/api/v1/document-checklist-items/"+check.id,token,{method:"PATCH",body:JSON.stringify({status,document_id:documentId,notes:check.notes||""})});const v=await request<{items:DocumentCheck[];summary:NonNullable<typeof checklistSummary>}>("/api/v1/applications/"+docAppId+"/document-checklist",token);setDocumentChecks(v.items);setChecklistSummary(v.summary);notify("Checklist review saved.");}
  catch(e){notify(e instanceof Error?e.message:"Could not update checklist item");}
 }
 async function saveChecklistTemplate(e:FormEvent<HTMLFormElement>){
  e.preventDefault();
  const items=checklistTemplateText.split("\n").map(line=>line.trim()).filter(Boolean).map(line=>{const [key,label,required="true"]=line.split("|").map(part=>part.trim());return {key,label,required:required.toLowerCase()==="true"};});
  if(items.some(item=>!item.key||!item.label)){notify("Use one line per item: key | label | true/false");return;}
  try{await request("/api/v1/document-checklists/templates",token,{method:"PUT",body:JSON.stringify({application_type:checklistType,items})});notify("Checklist template saved. Verify it against current official instructions.");}
  catch(e){notify(e instanceof Error?e.message:"Could not save checklist template");}
 }
 async function uploadDocument(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!selectedFile||!docAppId){notify("Choose an application and a file first.");return;}const body=new FormData();body.append("file",selectedFile);try{await request("/api/v1/applications/"+docAppId+"/documents",token,{method:"POST",body});setSelectedFile(null);(e.currentTarget as HTMLFormElement).reset();setDocuments(await request<DocumentRow[]>("/api/v1/applications/"+docAppId+"/documents",token));notify("Document uploaded to private local storage.");}catch(err){notify(err instanceof Error?err.message:"Upload failed");}}
 async function downloadDocument(d:DocumentRow){try{const res=await fetch(API+"/api/v1/documents/"+d.id+"/download",{headers:{Authorization:"Bearer "+token}});if(!res.ok)throw new Error("Download failed");const blob=await res.blob();const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=d.original_name;a.click();URL.revokeObjectURL(url);}catch(err){notify(err instanceof Error?err.message:"Download failed");}}
 async function saveWorkflowConfig(e:FormEvent<HTMLFormElement>){e.preventDefault();const next=stageText.split("\n").map(x=>x.trim()).filter(Boolean);try{const result=await request<{name:string;stages:string[]}>("/api/v1/workflow/config",token,{method:"PUT",body:JSON.stringify({name:workflowName,stages:next})});setStages(result.stages);setStageText(result.stages.join("\n"));notify("Workflow configuration saved. Review with competent authorities before operational use.");await loadAll();}catch(err){notify(err instanceof Error?err.message:"Could not save workflow");}}
 async function saveApplicationRoute(e:FormEvent<HTMLFormElement>){
  e.preventDefault();
  const next=routeStagesText.split("\n").map(x=>x.trim()).filter(Boolean);
  try{
   const result=await request<WorkflowRoute>("/api/v1/workflow/routes",token,{method:"PUT",body:JSON.stringify({application_type:routeType,stages:next})});
   setApplicationRoutes(previous=>[...previous.filter(route=>route.application_type!==result.application_type),result].sort((a,b)=>a.application_type.localeCompare(b.application_type)));
   notify("Application-type route saved. Confirm the route against official requirements before operational use.");
   await loadAll();
  }catch(err){notify(err instanceof Error?err.message:"Could not save application-type route");}
 }
 async function saveComplianceReview(e:FormEvent<HTMLFormElement>){
  e.preventDefault();if(!complianceReview)return;
  const draft=complianceReview;
  if(draft.status==="Non-Compliant"&&!draft.notes.trim()){notify("Add review notes before marking a task Non-Compliant.");return;}
  setComplianceReviewBusy(true);
  try{
   const updated=await request<Compliance>("/api/v1/compliance/"+draft.item.id,token,{method:"PATCH",body:JSON.stringify({status:draft.status,notes:draft.notes.trim(),due_date:draft.due_date||null,assigned_to:draft.assigned_to.trim()||null})});
   setCompliance(previous=>previous.map(item=>item.id===updated.id?{...item,...updated}:item));
   setComplianceReview(null);notify("Compliance review saved and task history recorded.");await loadAll();
  }catch(err){notify(err instanceof Error?err.message:"Could not save compliance review");}
  finally{setComplianceReviewBusy(false);}
 }
 async function requestCollegeCorrection(){
  if(!complianceReview)return;const draft=complianceReview;const reason=draft.notes.trim();
  if(!reason){notify("Add the correction reason in review notes first.");return;}
  setComplianceReviewBusy(true);
  try{
   const note="Correction requested from institution by "+(user?.full_name||user?.username||"Compliance Officer")+": "+reason;
   const updated=await request<Compliance>("/api/v1/compliance/"+draft.item.id,token,{method:"PATCH",body:JSON.stringify({status:"Under Review",notes:note,due_date:draft.due_date||null,assigned_to:draft.assigned_to.trim()||null})});
   setCompliance(previous=>previous.map(item=>item.id===updated.id?{...item,...updated}:item));
   setComplianceReview(null);notify("Correction request recorded on the compliance task. Email delivery is not configured by this action.");await loadAll();
  }catch(err){notify(err instanceof Error?err.message:"Could not record correction request");}
  finally{setComplianceReviewBusy(false);}
 }
 async function openFindingEvidence(item:ComplianceAutomationResult["issues"][number]){
  const app=apps.find(row=>row.id===item.application_id);
  if(!app){notify("Application record is not loaded. Refresh the page and try again.");return;}
  setDocAppId(app.id);setPage("Documents");notify("Opened document register for "+(item.application_no||app.application_no)+". Check the source record and verify evidence manually.");
 }
 async function takeActionOnFinding(item:ComplianceAutomationResult["issues"][number]){
  const existing=compliance.find(task=>task.application_id===item.application_id&&task.title===item.requirement);
  if(existing){
   setComplianceReview({item:existing,status:existing.status,notes:existing.notes||item.detail,due_date:existing.due_date?existing.due_date.slice(0,10):"",assigned_to:existing.assigned_to||user?.full_name||""});
   notify("Existing compliance task opened for review.");return;
  }
  try{
   const created=await request<Compliance>("/api/v1/compliance",token,{method:"POST",body:JSON.stringify({application_id:item.application_id,title:item.requirement,category:item.category,due_date:null,assigned_to:user?.full_name||"Compliance Officer",notes:item.detail})});
   setCompliance(previous=>[created,...previous]);
   setComplianceReview({item:created,status:created.status,notes:created.notes||item.detail,due_date:created.due_date?created.due_date.slice(0,10):"",assigned_to:created.assigned_to||user?.full_name||""});
   notify("Finding converted into an actionable compliance task.");
   await loadAll();
  }catch(err){
   const existingAfterRefresh=compliance.find(task=>task.application_id===item.application_id&&task.title===item.requirement);
   if(existingAfterRefresh){setComplianceReview({item:existingAfterRefresh,status:existingAfterRefresh.status,notes:existingAfterRefresh.notes||item.detail,due_date:existingAfterRefresh.due_date?existingAfterRefresh.due_date.slice(0,10):"",assigned_to:existingAfterRefresh.assigned_to||user?.full_name||""});return;}
   notify(err instanceof Error?err.message:"Could not create compliance task from this finding.");
  }
 }
 async function runComplianceAutomation(){
  if(!["admin","officer","compliance_officer"].includes(user?.role||"")){notify("Your role is not authorised to run compliance automation.");return;}
  if(complianceAutomationBusy)return;
  setComplianceAutomationBusy(true);
  try{
   const result=await request<ComplianceAutomationResult>("/api/v1/compliance/automation/run",token,{method:"POST",body:"{}"});
   setComplianceAutomationResult(result);setComplianceAutomationLastRun(result);
   notify(result.status==="Completed"?(result.issues_detected===0?"Compliance automation completed successfully. No issues detected.":`Compliance automation completed: ${result.issues_detected} issue(s), ${result.tasks_created} task(s) created.`):"Compliance automation finished with status "+result.status+".");
   await loadAll();
   try{setComplianceAutomationLastRun(await request<ComplianceAutomationResult|null>("/api/v1/compliance/automation/last-run",token));}catch{}
  }catch(e){const message=e instanceof Error?e.message:"Compliance automation request failed";notify(message);setComplianceAutomationResult({run_id:"",status:"Failed",started_at:new Date().toISOString(),completed_at:new Date().toISOString(),applications_scanned:0,documents_checked:0,issues_detected:0,tasks_created:0,tasks_updated:0,tasks_skipped:0,alerts_created:0,errors:[message],warnings:[],issues:[]});}
  finally{setComplianceAutomationBusy(false);}
 }
 async function runAutomation(){
  if(!canWrite){notify("Admin or officer role required to run automation.");return;}
  setAutomationBusy(true);
  try{
   const result=await request<{scanned:number;assigned:number;alerts_created:number;message:string}>("/api/v1/automation/run",token,{method:"POST",body:"{}"});
   setAutomationResult(result);
   notify("Automation complete: "+result.scanned+" cases scanned, "+result.alerts_created+" alerts created.");
   await loadAll();
  }catch(e){notify(e instanceof Error?e.message:"Automation run failed");}
  finally{setAutomationBusy(false);}
 }
